html:
{%- import "altor_project/templates/print/altor_print.html" as ap with context -%}
{%- set c = altor_company(doc.company, doc) -%}
{{ ap.styles(c) }}
<style>
  .ap .grid { margin: 10px 0 0; table-layout: fixed; }
  .ap .grid td { border: 1px solid #e4e7eb; padding: 4px 7px; font-size: 8.8pt; vertical-align: top; }
  .ap .grid td.k { background: #f3f6fa; color: #52606d; width: 19%; white-space: nowrap; }
  .ap .grid td.v { width: 31%; font-weight: 600; }
  .ap .grid tr.cap td { background: {{ c.accent }}; color: #fff; font-weight: 700; font-size: 8pt; text-transform: uppercase; letter-spacing: .6px; border-color: {{ c.accent }}; }
  .ap .cert td.ref, .ap .cert th.ref { text-align: center; width: 5%; }
  .ap .cert td.calc { background: #eef3f9 !important; font-weight: 700; }
  .ap .cert tr.grand td { background: {{ c.accent }} !important; color: #fff; font-weight: 700; border-color: {{ c.accent }}; }
  .ap .psign td { border: 1px solid #d9e2ec; text-align: center; vertical-align: top; padding: 5px 4px; font-size: 8pt; width: 14.28%; }
  .ap .psign th { background: #f3f6fa; border: 1px solid #d9e2ec; font-size: 7.5pt; letter-spacing: .5px; padding: 4px; color: #102a43; }
  .ap .psign .space { height: 54px; }
  .ap .psign img { max-height: 52px; max-width: 110px; }
  .ap .erp { margin-top: 10px; font-size: 7.8pt; color: #52606d; }
  .ap .erp td { border: 1px solid #e4e7eb; padding: 3px 6px; }
</style>
{%- set cur = doc.currency or "" -%}
{%- macro pair(no, validity) -%}{{ no or "" }}{% if validity %}{% if no %} &nbsp;/&nbsp; {% endif %}{{ ap.date(validity) }}{% endif %}{%- endmacro -%}
{%- macro user(u) -%}{{ frappe.utils.get_fullname(u) if u else "" }}{%- endmacro -%}
<div class="ap">
{{ ap.header(c, "SUBCONTRACTOR'S PAYMENT CERTIFICATE", None, [
    ["Certificate No.", doc.name],
    ["Version", doc.version],
    ["Status", doc.approval_status if doc.docstatus == 0 else ("Cancelled" if doc.docstatus == 2 else "Certified")]
]) }}

<table class="grid">
  <tr><td class="k">Subcontractor / Payee</td><td class="v">{{ doc.supplier_name or doc.supplier }}</td><td class="k">Certificate No.</td><td class="v">{{ doc.name }}</td></tr>
  <tr><td class="k">Agreement Reference</td><td class="v">{{ doc.subcontract_work_order or "" }}</td><td class="k">Certificate Date</td><td class="v">{{ ap.date(doc.certificate_date) }}</td></tr>
  <tr><td class="k">Subcontract Type</td><td class="v">{{ doc.subcontract_type or "" }}</td><td class="k">Application No.</td><td class="v">{{ doc.application_no or "" }}</td></tr>
  <tr><td class="k">Site / Project</td><td class="v">{{ doc.project }}{% if doc.project_name and doc.project_name != doc.project %} &ndash; {{ doc.project_name }}{% endif %}</td><td class="k">Application Date</td><td class="v">{{ ap.date(doc.application_date) }}</td></tr>
  <tr><td class="k">Scope of Work</td><td class="v">{{ doc.scope_of_work or "" }}</td><td class="k">Application Recorded</td><td class="v">{{ ap.date(doc.application_recorded) }}</td></tr>
  <tr><td class="k">Project / Budget Code</td><td class="v">{{ doc.project_budget or "" }}{% if doc.cost_center %}<div class="muted" style="font-weight:400">Division: {{ doc.cost_center }}</div>{% endif %}</td><td class="k">Payment Due Date</td><td class="v">{{ ap.date(doc.payment_due_date) }}</td></tr>
</table>

<table class="grid">
  <tr class="cap"><td colspan="4">Securities, Insurances and Licences (No. &amp; Validity)</td></tr>
  <tr><td class="k">APG</td><td class="v">{{ pair(doc.apg_no, doc.apg_validity) }}</td><td class="k">WC Insurance</td><td class="v">{{ pair(doc.wc_insurance_no, doc.wc_insurance_validity) }}</td></tr>
  <tr><td class="k">PG</td><td class="v">{{ pair(doc.pg_no, doc.pg_validity) }}</td><td class="k">CPM Insurance</td><td class="v">{{ pair(doc.cpm_insurance_no, doc.cpm_insurance_validity) }}</td></tr>
  <tr><td class="k">TPL</td><td class="v">{{ pair(doc.tpl_no, doc.tpl_validity) }}</td><td class="k">PI</td><td class="v">{{ pair(doc.pi_no, doc.pi_validity) }}</td></tr>
  <tr><td class="k">Vehicle Insurance</td><td class="v">{{ pair(doc.vehicle_insurance_no, doc.vehicle_insurance_validity) }}</td><td class="k">Cargo Insurance</td><td class="v">{{ pair(doc.cargo_insurance_no, doc.cargo_insurance_validity) }}</td></tr>
  <tr><td class="k">Trade License</td><td class="v">{{ pair(doc.trade_license_no, doc.trade_license_validity) }}</td><td class="k">VAT Certificate / TRN</td><td class="v">{{ doc.vat_trn or "" }}</td></tr>
</table>

<table class="grid">
  <tr class="cap"><td colspan="4">Contract Summary</td></tr>
  <tr><td class="k">Subcontract Amount</td><td class="v right">{{ ap.amt(doc.subcontract_amount) }}</td><td class="k">Month</td><td class="v">{{ doc.period_month or "" }}</td></tr>
  <tr><td class="k">Approved Amendments / Variations</td><td class="v right">{{ ap.amt(doc.approved_variations) }}</td><td class="k">Duration</td><td class="v">{{ doc.duration or "" }}</td></tr>
  <tr><td class="k">Other Adjustments</td><td class="v right">{{ ap.amt(doc.other_adjustments) }}</td><td class="k">Commencement Date</td><td class="v">{{ ap.date(doc.commencement_date) }}</td></tr>
  <tr><td class="k"><b>Revised Contract Amount</b></td><td class="v right"><b>{{ ap.amt(doc.revised_contract_amount) }}</b></td><td class="k">Cumulative Work %</td><td class="v">{% if doc.cumulative_work_percent %}{{ frappe.utils.flt(doc.cumulative_work_percent, 2) }}%{% endif %}</td></tr>
  <tr><td class="k">Settlement / Waiver Figure</td><td class="v right">{% if doc.settlement_figure %}{{ ap.amt(doc.settlement_figure) }}{% endif %}</td><td class="k">Currency</td><td class="v">{{ cur }}</td></tr>
</table>

{%- set L = {} -%}
{%- for row in doc.lines %}{% set _ = L.update({row.ref: row}) %}{% endfor -%}
{%- macro line(ref) -%}
{%- set r = L.get(ref) -%}
{%- if r %}
<tr><td>{{ r.description }}</td><td class="ref">{{ ref }}</td><td class="right">{% if r.rate %}{{ frappe.utils.flt(r.rate, 2) }}%{% endif %}</td>
<td class="right">{{ ap.amt(r.cumulative) }}</td><td class="right">{{ ap.amt(r.previous) }}</td><td class="right">{{ ap.amt(r.this_period) }}</td><td>{{ r.notes or "" }}</td></tr>
{%- endif %}
{%- endmacro -%}
{%- macro calc(label, ref, key, rate="", cls="") -%}
<tr class="{{ cls }}"><td class="calc">{{ label }}</td><td class="ref calc">{{ ref }}</td><td class="right calc">{{ rate }}</td>
<td class="right calc">{{ ap.amt(doc.get(key ~ "_cumulative")) }}</td><td class="right calc">{{ ap.amt(doc.get(key ~ "_previous")) }}</td><td class="right calc">{{ ap.amt(doc.get(key ~ "_this_period")) }}</td><td class="calc"></td></tr>
{%- endmacro -%}

<div class="sec" style="page-break-inside:auto">
<div class="sec-title">Payment Certification &nbsp;|&nbsp; {{ cur }}</div>
<table class="items cert">
  <thead><tr><th>Description</th><th class="ref">Ref.</th><th class="right">Rate / %</th><th class="right">Cumulative</th><th class="right">Previous</th><th class="right">This Period</th><th>Notes</th></tr></thead>
  <tbody>
    {{ line("A") }}{{ line("B") }}{{ line("C") }}{{ line("D") }}
    {{ calc("GROSS AMOUNT", "E", "gross") }}
    {{ line("F") }}{{ line("G") }}
    {{ calc("Remaining Advance Payment", "H", "remaining_advance") }}
    {{ line("I") }}{{ line("J") }}{{ line("K") }}{{ line("L") }}
    {{ calc("TOTAL DEDUCTIONS", "O", "total_deductions") }}
    {{ calc("NET AMOUNT (EXCL. VAT)", "P", "net_excl_vat") }}
    {{ calc("VATABLE TURNOVER", "Q", "net_excl_vat") }}
    {{ calc("VAT", "R", "vat_amount", frappe.utils.flt(doc.vat_rate, 2) ~ "%") }}
    {{ calc("NET AMOUNT INCLUDING VAT", "S", "net_incl_vat", "", "grand") }}
  </tbody>
</table>
</div>
<div class="words" style="margin:8px 0 0"><span class="muted">Amount in words (this period):</span> <b>{{ doc.in_words or "-" }}</b></div>

<div class="sec">
<div class="sec-title">Back Charges / Other Recoveries</div>
<table class="items">
  <thead><tr><th>Description</th><th>Reference</th><th>Date</th><th class="right">Amount</th><th class="right">VAT</th><th class="right">Total</th><th>Remarks</th></tr></thead>
  <tbody>
  {%- for r in doc.back_charges %}
    <tr><td>{{ r.description }}</td><td>{{ r.reference or "" }}</td><td>{{ ap.date(r.date) }}</td><td class="right">{{ ap.amt(r.amount) }}</td><td class="right">{{ ap.amt(r.vat) }}</td><td class="right">{{ ap.amt(r.total) }}</td><td>{{ r.remarks or "" }}</td></tr>
  {%- else %}
    <tr><td colspan="7" class="muted center">No back charges</td></tr>
  {%- endfor %}
  {%- if doc.back_charges %}
    <tr class="sub"><td colspan="5">Total Back Charges</td><td class="right">{{ ap.amt(doc.total_back_charges) }}</td><td></td></tr>
  {%- endif %}
  </tbody>
</table>
</div>

{{ ap.section("Payment Terms / Notes", doc.payment_terms and doc.payment_terms | replace("\n", "<br>")) }}
{{ ap.section("Remarks", doc.remarks and doc.remarks | replace("\n", "<br>")) }}

<table class="psign" style="margin-top:16px;page-break-inside:avoid">
  <tr><th>INITIATED BY</th><th>REVIEWED BY</th><th>CHECKED BY</th><th>AUTHORIZED BY</th><th>APPROVED BY</th><th>DATE</th><th>STAMP</th></tr>
  <tr>
    {%- for u in [doc.initiated_by, doc.reviewed_by, doc.checked_by, doc.authorized_by, doc.approved_by] %}
    <td><div class="space"></div><div>{{ user(u) or "&nbsp;" }}</div><div class="muted">Name / Sign</div></td>
    {%- endfor %}
    <td><div class="space"></div><div>{{ ap.date(doc.approved_on) or "&nbsp;" }}</div></td>
    <td><div class="space">{% if c.stamp and doc.docstatus == 1 %}<img src="{{ c.stamp }}">{% endif %}</div></td>
  </tr>
</table>

<table class="erp">
  <tr><td><b>Project ID:</b> {{ doc.project }}</td><td><b>Client PO:</b> {{ doc.client_po or "-" }}</td><td><b>Payment Application:</b> {{ doc.application_no or "-" }}</td>
  <td><b>Certificate No.:</b> {{ doc.name }}</td><td><b>Version:</b> {{ doc.version or 1 }}</td><td><b>Approval Status:</b> {{ doc.approval_status }}</td></tr>
  {%- if doc.previous_certificate %}<tr><td colspan="6"><b>Previous Certificate:</b> {{ doc.previous_certificate }}{% if doc.amended_from %} &nbsp;|&nbsp; <b>Amended From:</b> {{ doc.amended_from }}{% endif %}</td></tr>{% endif %}
</table>
{{ ap.footer(c) }}
</div>
